/**
 * R8.2 Workstream B — persist-mode production proof wiring.
 *
 * `--persist-audit` must never persist decisions generated by the
 * filesystem-only `FilesystemProofResolver`. This module constructs the full
 * production proof graph used by persist mode:
 *
 *   - SourceDocument client: the real Prisma client;
 *   - parse-job client: the same Prisma client;
 *   - S3 object reader: AWS SDK adapter (existing SDK, no second AWS config);
 *   - byte locator reader: composite filesystem + S3 reader;
 *   - proof resolver: `CompositeProofResolver` in `production_proof` mode;
 *   - repository: Prisma repository created from the SAME client.
 *
 * Fail-closed: wiring fails (before any persistence) when the Prisma client
 * cannot reach the database — the SourceDocument/parse-job client is then
 * unavailable and no proof bundle can be produced. Policy-required archive
 * and parser-run dependencies are additionally enforced inside
 * `CompositeProofResolver.resolve()` before any result exists.
 *
 * Inspect mode never calls this module; it uses `FilesystemProofResolver`,
 * which cannot create durable trusted audit evidence.
 */
import type { PrismaClient } from '@prisma/client';
import { CompositeProofResolver } from './composite-proof-resolver.js';
import type { TrustedVerificationProofResolverV1 } from './trusted-proof-types.js';
import {
  FilesystemByteLocatorReader,
  S3ByteLocatorReader,
  CompositeByteLocatorReader,
} from './trusted-byte-locator-reader.js';
import { SdkS3ProofClient } from './s3-proof-adapters.js';
import type { ParserOutputProofSource } from './parser-output-proof-source.js';
import {
  CompositeParserOutputProofSource,
  FilesystemParserOutputProofAdapter,
  LlamaParseParserOutputProofAdapter,
} from './parser-output-proof-adapters.js';
import type { BudgetVerificationRepositoryV1 } from '../persistence/verification-repository.js';
import { createPrismaBudgetVerificationRepository } from '../persistence/prisma-budget-verification.repository.js';

/** Raised when persist-mode wiring cannot establish the production proof graph. */
export class ProductionProofWiringError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ProductionProofWiringError';
  }
}

export interface ProductionProofWiringOptions {
  /** The Prisma client shared by the repository and both proof clients. */
  prisma: PrismaClient;
  /**
   * Approved filesystem prefixes for the byte locator reader. Empty list
   * means all local paths are accepted (the reader's documented default).
   */
  approvedFilesystemPrefixes?: readonly string[];
  /**
   * Injected SdkS3ProofClient for tests. When omitted, one is created from
   * the standard AWS environment conventions (+ optional test-only
   * BUDGET_VERIFICATION_S3_ENDPOINT).
   */
  s3ProofClient?: SdkS3ProofClient;
  /** Skip the eager database connectivity probe (unit tests with fakes). */
  skipDatabaseProbe?: boolean;
  /**
   * Root directory of the Phase 3 content-addressed local parser artifact
   * store (default: `defense-budget-parser-artifacts` under cwd).
   */
  parserArtifactStoreRootDir?: string;
  /** Bucket holding persisted LlamaParse output objects. */
  llamaParseOutputBucket?: string;
  /** Fully custom parser-output proof source (overrides the default build). */
  parserOutputProofSource?: ParserOutputProofSource;
}

export interface ProductionProofWiringResult {
  /** The production proof resolver. Always `production_proof` mode. */
  proofResolver: TrustedVerificationProofResolverV1;
  /** Proof that the constructed resolver is the composite production resolver. */
  compositeResolver: CompositeProofResolver;
  /** Repository created from the same Prisma client. */
  repository: BudgetVerificationRepositoryV1;
  /** Close AWS SDK resources. The caller closes Prisma itself. */
  dispose(): Promise<void>;
}

/**
 * Wire the full production proof boundary for persist mode.
 *
 * Throws `ProductionProofWiringError` before any persistence can occur when:
 *   - the database (SourceDocument/parse-job client) is unreachable.
 *
 * Policy-level dependency failures (missing archive S3 proof, missing parser
 * proof dependencies, unresolvable authoritative source bytes, unprovable
 * references) are thrown by `CompositeProofResolver.resolve()` before the
 * service persists anything.
 */
export async function wireProductionProofBoundary(
  options: ProductionProofWiringOptions,
): Promise<ProductionProofWiringResult> {
  const { prisma } = options;

  // Fail closed before persistence when the SourceDocument client is
  // unavailable: the Prisma client must actually connect.
  if (!options.skipDatabaseProbe) {
    try {
      await prisma.$connect();
    } catch (err) {
      throw new ProductionProofWiringError(
        `persist mode requires a reachable database for the SourceDocument client: ${
          (err as Error).message
        }`,
      );
    }
  }

  // The same Prisma client serves both proof clients and the repository —
  // one transactional boundary, one identity.
  const sourceDocumentClient = prisma;
  const parseJobClient = prisma;

  const s3ProofClient = options.s3ProofClient ?? new SdkS3ProofClient();
  const s3ObjectReader = s3ProofClient;
  const s3ByteReader = new S3ByteLocatorReader(s3ProofClient);
  const filesystemByteReader = new FilesystemByteLocatorReader(
    options.approvedFilesystemPrefixes ?? [],
  );
  const byteLocatorReader = new CompositeByteLocatorReader(filesystemByteReader, s3ByteReader);

  // R8.2 Workstream C: independent parser-output proof. Reuse the existing
  // Phase 3 content-addressed parser infrastructure through narrow
  // read-only adapters — Phase 2 never initiates parsing or escalation.
  const parserOutputProofSource: ParserOutputProofSource =
    options.parserOutputProofSource ??
    new CompositeParserOutputProofSource({
      localSource: new FilesystemParserOutputProofAdapter(
        options.parserArtifactStoreRootDir ?? 'defense-budget-parser-artifacts',
      ),
      llamaParseSource: new LlamaParseParserOutputProofAdapter({
        parseJobClient,
        byteLocatorReader,
        outputBucket: options.llamaParseOutputBucket ?? 'capiro-defense-budget-raw',
      }),
    });

  const proofResolver = new CompositeProofResolver({
    mode: 'production_proof',
    sourceDocumentClient,
    parseJobClient,
    s3Reader: s3ObjectReader,
    byteLocatorReader,
    parserOutputProofSource,
  });

  const repository = createPrismaBudgetVerificationRepository(prisma);

  return {
    proofResolver,
    compositeResolver: proofResolver,
    repository,
    async dispose(): Promise<void> {
      // Close AWS clients; the CLI owns the Prisma client lifecycle.
      if (!options.s3ProofClient) {
        await s3ProofClient.destroy();
      }
    },
  };
}
